INSERT INTO public.handoff_requirements(id,code,name,category,tier,done_when,proof_needed,status,notes,sort_order) VALUES
('1e1e61e1-9556-5ab2-9d20-2fdb40503d93','SAF-01','Smoke alarms','Safety','essential','Pass only if the required number and locations are confirmed, alarms test successfully, units are within manufacturer service life, and photos/location inventory match the PID.','Alarm-location inventory; label photos; test date/result; tester name.','proposed','Proposed. Micah and Kati have not signed off.',0),
('0283e26e-7b4d-5a3b-b31c-add231b6e595','SAF-02','Carbon monoxide alarms','Safety','essential','All legally or contractually required CO alarms present, within service life and tested; PID and listing tell the same story.','Location/photo; date labels; test result; applicability reason.','proposed','Proposed. Micah and Kati have not signed off.',10),
('8ce839f0-9b9c-5ac6-87c2-60d4aec52c25','SAF-03','Fire extinguisher','Safety','essential','Required extinguisher present, accessible and in acceptable condition; tag/gauge/service requirement reviewed.','Placement photo; tag/gauge photo; inspection date.','proposed','Proposed. Micah and Kati have not signed off.',20),
('e6bc43de-17ea-5d1f-a258-450f2b0ef086','SAF-04','Emergency exit and trip hazards','Safety','essential','Exits open freely; no blocked required exit or material fall hazard; relevant defect corrected.','Walkthrough/video; defect photos and repairs.','proposed','Proposed. Micah and Kati have not signed off.',30),
('b262ecaf-940b-57d3-9ca5-a563fe3e9c44','SAF-05','First-aid supplies','Safety','essential','Present and usable; location appears in property instructions.','Photo and kit location.','proposed','Proposed. Micah and Kati have not signed off.',40),
('8d90758f-9796-52b3-80f4-972c3cf95df1','SAF-06','Dryer vent safety','Safety','essential','Vent fully cleaned during onboarding, dryer runs normally, and before/after photos and cleaning date are recorded.','Service invoice/photos or documented inspection and appliance test.','proposed','Proposed. Micah and Kati have not signed off.',50),
('a713f768-b73f-5173-a86f-11fc3ef61262','ACC-01','Primary guest entry','Access','essential','Entry succeeds using guest directions; deadbolt extends/retracts freely; code is current; emergency egress operates.','Timestamped video of closing, locking, unlocking; entry instructions; test result.','proposed','Proposed. Micah and Kati have not signed off.',60),
('6560594d-9fa4-5d89-b004-cefb0a190de5','ACC-02','Backup emergency entry','Access','essential','Every required key is present, tagged and tested, and Operations can enter if primary electronics or network fail.','Test record, key inventory photo, approved secure storage location (codes restricted).','proposed','Proposed. Micah and Kati have not signed off.',70),
('6b7c424a-43e5-52e7-a54d-285285dcc89f','ACC-03','Guest door handles','Access','essential','Every guest entrance follows approved hardware design and operates correctly without forcing.','Door-hardware photos and operation video.','proposed','Proposed. Micah and Kati have not signed off.',80),
('ed4eb617-4beb-5115-8e14-e83956f29581','ACC-04','Garage access and remote','Access','essential','Advertised garage access works; guest cannot accidentally lose essential property entry; equipment passes manufacturer safety checks.','Count, photos, test result, operating notes.','proposed','Proposed. Micah and Kati have not signed off.',90),
('8c342adb-89b9-5273-b60a-6fa3b8c77c36','ACC-05','Smart lock connection and batteries','Access','essential','Lock reliably accepts valid code, responds to control system where required, and power/low-battery details are recorded.','Connection screenshot, code test video (mask secret), battery date/brand.','proposed','Proposed. Micah and Kati have not signed off.',100),
('0fa9bebe-83c8-51a4-a5be-c3531def6c16','ACC-06','Alarm or security system','Access','micah','Operations can manage equipment without triggering avoidable alarm or losing access; instructions and contacts verified.','Equipment photo, authorized test notes, restricted credential record.','proposed','Proposed. Micah and Kati have not signed off.',110),
('edbfef96-6ccc-5ebd-afe6-85ad302474fa','ACC-07','Community keys and fobs','Access','micah','Guests can access every advertised/essential feature during its advertised season and hours.','Fob photo/count, test date, rule/source verification.','proposed','Proposed. Micah and Kati have not signed off.',120),
('9d8cb333-f883-5f9b-87d4-011303bdc660','ACC-08','Security cameras and device accounts','Access','essential','All cameras are on ARHA accounts, the monitoring plan is active, no indoor cameras, and every camera is accurately disclosed on every listing channel.','Camera location photos, account screenshot, plan expiration date, listing disclosure screenshot.','proposed','Proposed. Micah and Kati have not signed off.',130),
('d1163e6e-e545-5b12-9e2a-96b489a7aebd','WAT-01','Water shutoff emergency instructions','Water','essential','Operations has reliable isolation instructions or a documented qualified emergency response arrangement; accuracy verified on site.','Wide-location photo, valve close-up, directions, verifier and safe test/pro confirmation.','proposed','Proposed. Micah and Kati have not signed off.',140),
('d500baac-02ec-5f52-a49e-83aceb1bfa71','WAT-02','Active leaks and visible water damage','Water','essential','No active leak or unexplained material water damage remains unresolved; known prior damage documented.','Inspection photos, repair records, follow-up test.','proposed','Proposed. Micah and Kati have not signed off.',150),
('2d9b25ca-72fd-5f25-a214-a341e4eaff78','WAT-03','Toilets, sinks and drains','Water','essential','All fixtures work normally without leak, backup, persistent running or guest-impacting blockage.','Fixture checklist by room; issue photos; repair confirmation.','proposed','Proposed. Micah and Kati have not signed off.',160),
('bbc00e9a-afae-5fbb-83b8-6b8aaa9428e1','WAT-04','Showers and hot water','Water','essential','Every advertised bathing fixture is usable, supplies hot water and drains without visible leak.','Test result by bathroom, photos of issues, verifier.','proposed','Proposed. Micah and Kati have not signed off.',170),
('1b914dd1-8cb0-5e7a-a165-397d85521760','WAT-05','Water heater inventory','Water','essential','Accurate location and emergency action documented; no active hazard; key available information or documented unknown with follow-up where truly noncritical.','Label photo, location photo, condition evidence and any service report.','proposed','Proposed. Micah and Kati have not signed off.',180),
('7e528419-a65f-5ca1-b614-fa2c4c7f4ce9','HVAC-01','Heating and air conditioning','Heating and cooling','essential','Essential climate control works for season and booked period; filter/service instructions are documented.','Thermostat and equipment photos; test result; model/filter detail.','proposed','Proposed. Micah and Kati have not signed off.',190),
('c24dcf2e-11f0-5551-8b1a-787bc79381a5','ELEC-01','Electricity and electrical hazards','Electrical','essential','Power operational and no known accessible electrical hazard remains.','Panel location photo; issues log; qualified service confirmation if relevant.','proposed','Proposed. Micah and Kati have not signed off.',200),
('3a37f1d6-1554-5f33-ab3b-23ad0549b2cd','NET-01','Internet and router','Internet','essential','Advertised internet functions, smart devices remain connected, and staff can find router and approved troubleshooting steps.','Connection test date/result, router photo, network identification (password stored securely).','proposed','Proposed. Micah and Kati have not signed off.',210),
('a8fa9362-8883-5726-a427-eb59342e5d0d','APP-01','Dishwasher and disposal','Appliances','micah','Installed advertised appliances operate without error, backing up or leak.','Test log, photos of equipment and under-sink area.','proposed','Proposed. Micah and Kati have not signed off.',220),
('3b478ec8-270c-53c8-8f7a-02f8cfd75b42','APP-02','Laundry appliances','Appliances','micah','Laundry appliances work as advertised without leaks or safety warning signs.','Cycle result; model labels; appliance photos.','proposed','Proposed. Micah and Kati have not signed off.',230),
('84551c4d-8df3-59c6-bc11-b0330775146d','APP-03','Kitchen essential appliances','Appliances','essential','Cooking and food-storage essentials work and listing does not promise broken features.','Room/appliance checklist, model labels, exception notes.','proposed','Proposed. Micah and Kati have not signed off.',240),
('37f09ea9-740d-5165-8fc4-5b2bd23460ca','APP-04','TV and connected account setup','Appliances','micah','TVs work as described without exposing owner personal accounts or payments.','TV inventory, model photos, working-menu photo without private details.','proposed','Proposed. Micah and Kati have not signed off.',250),
('b20a1e2f-bf9f-575b-80ff-ec9df56ccd90','CLN-01','Deep clean completed','Cleaning','essential','Property is free of visible dirt, odors, debris, residue or conditions that will reasonably trigger first-arrival cleanliness complaints.','Dated completed-clean record and room photos; supervisor review.','proposed','Proposed. Micah and Kati have not signed off.',260),
('368616c2-cd62-5963-856b-36b65c6af79f','CLN-02','Pest evidence','Cleaning','essential','First pest control service completed and no known active infestation.','Findings photo, treatment/service details where applicable.','proposed','Proposed. Micah and Kati have not signed off.',270),
('66e1f0fe-6e91-5002-95fc-0e5d13c368bd','COND-01','Full condition video and photos','Condition','essential','Baseline reasonably documents existing condition and known exceptions without concealing damage.','Dated full video, room photos, issue inventory linked to repairs.','proposed','Proposed. Micah and Kati have not signed off.',280),
('5da0fc88-0f39-5097-b356-7242295ebf3d','COND-02','Known inspection and repair items','Condition','essential','All known items accounted for, safety/property issues corrected, and owner refusals/disclosures retained; no critical unresolved item hidden.','Report, item-by-item tracker, owner decision records, photos.','proposed','Proposed. Micah and Kati have not signed off.',290),
('6ba009dd-c619-58e3-b70c-6ff70509f558','LIN-01','Beds, linens, protective covers','Linens and bath','essential','Every advertised sleeping place is usable and correctly outfitted; backup linens inventoried and secured.','Room-by-room bed photo and count; linen-storage photo.','proposed','Proposed. Micah and Kati have not signed off.',300),
('8cc200fd-9272-5662-bce6-b5dd291879e8','LIN-02','Towels and basic bathroom supplies','Linens and bath','essential','Guest and backup supply minimums meet approved per-occupancy standard; each toilet has a usable plunger under proposed ARHA standard.','Count by room, storage photo.','proposed','Proposed. Micah and Kati have not signed off.',310),
('6484b63a-c879-55c2-a81d-40c7f44061eb','KIT-01','Dishes and kitchen inventory','Kitchen','micah','Count meets company standard and capacity; damaged or unsafe items replaced.','Inventory count and kitchen/cabinet photos.','proposed','Proposed. Micah and Kati have not signed off.',320),
('b8cb1dae-45e1-5f13-a667-1988051cd55e','FUR-01','Furnishings, storage and Never-Buy List','Furnishings','micah','No Never-Buy items in the home, storage and shelving in place, and no stained or damaged soft goods remain.','Room photos, closet and storage photos, purchase list checked against the Never-Buy List.','proposed','Proposed. Micah and Kati have not signed off.',330),
('3cdc2894-4ff4-5258-ab2f-ac39de83f432','STR-01','Owner/cleaning storage secure','Storage','essential','Owner items and restricted supplies secured; authorized team can open storage; supplies needed for essential operations available.','Storage location and lock test; inventory photo; secure access method.','proposed','Proposed. Micah and Kati have not signed off.',340),
('05c48c98-4969-5811-b132-99f221382149','SV-01','Trash provider and instructions','Services','essential','Accurate pickup instructions, adequate cans and no expected HOA violation from normal guest use.','Provider/source/date, cart photo and location.','proposed','Proposed. Micah and Kati have not signed off.',350),
('32893348-2c76-5ba1-8350-0093a265c8f3','SV-02','Landscape and pool service','Services','micah','Service arranged as needed for safe operations and property protection; all provider details accessible to Operations.','Provider/contact, service schedule, work confirmation, current photos.','proposed','Proposed. Micah and Kati have not signed off.',360),
('ef84f623-20aa-5f15-b3f9-96f6300ac6a8','SV-03','Seasonal maintenance and winterization','Services','micah','Owner decision and operational response are clear, viable and compatible with current bookings.','Owner written instruction, provider/contact, plan/date.','proposed','Proposed. Micah and Kati have not signed off.',370),
('b60ead67-d365-5c0b-abdc-d2ab9f90ca23','EQ-01','All maintainable equipment inventory','Equipment','essential','For each relevant device Operations can identify it, access it, know who maintains it, when service is due, and what owner approval/restrictions apply.','Label photo, equipment sheet, routine schedule and responsibility.','proposed','Proposed. Micah and Kati have not signed off.',380),
('0a59e5b4-99a1-5054-a3d4-c4eed88764c1','EQ-02','Robotic cleaner / iRobot plan','Equipment','micah','Device works if promised and has a documented maintenance owner; owner/guest accounts not exposed.','Working test, model photo, cleaning schedule and named owner.','proposed','Proposed. Micah and Kati have not signed off.',390),
('8b663fc3-b3f0-5d27-bfff-c115e7c801a1','OWN-01','Owner authorization and cost rules','Owner','essential','Operations can make time-sensitive decisions without guessing who may approve expense or maintain equipment.','Signed agreement reference, decision record, authorized contacts; restrict sensitive details.','proposed','Proposed. Micah and Kati have not signed off.',400),
('90d03210-330d-542b-82ca-3a48c37ef6dc','OWN-02','Owner personal belongings','Owner','essential','Guest cannot access sensitive owner property and ARHA can identify existing stored items.','Storage photo and item inventory where appropriate.','proposed','Proposed. Micah and Kati have not signed off.',410),
('0d4a2d05-475d-52aa-8a9f-4a4368421980','HOA-01','HOA, parking and occupancy rules','HOA and community','essential','ARHA understands applicable restrictions and can operate the planned stay type without known material conflict.','Rule copies/source/date, parking instructions, owner acknowledgment.','proposed','Proposed. Micah and Kati have not signed off.',420),
('daeeb7a6-20a9-5767-8dbc-1c48e7881e7d','HOA-02','Neighbor outreach','HOA and community','nonessential','Outreach, if required, complies with applicable law and community rules. Do NOT place unstamped flyers in mailboxes.','Method/date/contact note, permission if needed.','proposed','Proposed. Micah and Kati have not signed off.',430),
('dc24acd5-d36d-50e1-a5a0-700e98b513c1','LST-01','Listing details and amenities','Listing','essential','No material promise is wrong or inconsistent; limited/unavailable features correctly disclosed before guests book.','Signed listing comparison, screenshots from channels, property photos.','proposed','Proposed. Micah and Kati have not signed off.',440),
('d7632b9e-ad9d-586c-a0a6-70b0d74d4d0f','LST-02','Guest directions and guidebook','Listing','essential','Instructions work for someone unfamiliar with home and agree with actual configuration.','Current message and guidebook version; test results.','proposed','Proposed. Micah and Kati have not signed off.',450),
('e0328240-d318-5705-9546-6f3d364b994c','LST-03','Screening and fee setup','Listing','essential','Configured amount and program match documented currently approved company terms.','Plan screenshot, pricing owner confirmation and setup record.','proposed','Proposed. Micah and Kati have not signed off.',460),
('5febbd57-e978-55f0-a031-b238d6483a44','SYS-01','Systems setup confirmed by Kati','Systems','essential','Kati confirms every platform is complete and accurate, with no missing or placeholder data.','Kati''s sign-off with date; PID % Complete at 100%.','proposed','Proposed. Micah and Kati have not signed off.',470),
('f447026a-9bb2-5fcd-b43b-daa27db1bff6','GST-01','Independent mock guest check-in','Guest check-in','essential','Tester completes all critical arrival steps unassisted; every issue corrected and retested before Ops Live approval.','Tester name/date, step-by-step test record, entry video, screenshots with secrets hidden.','retired','Proposed removal',480),
('6099e7c4-a2c9-5e52-b9cf-7c4e4586edd9','FIN-01','Final home and handoff reconciliation','Final reconciliation','essential','No open essential gaps or expired exceptions; final home is in same approved state and Operations has all response information.','Approval record, exception log, last condition check, assignment confirmation.','proposed','Proposed. Micah and Kati have not signed off.',490)
